import React, { useState} from "react";

function Ead(){
    const [head, setHead] = useState('');
    const numb = head > 0 ? this.head : this.head = 0;

    return (
        <>
            <h1>{numb} + 7 = {Number(numb)+7}</h1>
            <input type="number" onChange={(e) => setHead(e.target.value)}/>
        </>
    )
}

export default Ead;
